INSERT INTO `wp_options` VALUES (929,'options_deposito_tenor_cards','a:4:{i:0;a:10:{s:5:\"tenor\";s:7:\"1 Bulan\";s:9:\"tenor_num\";i:1;s:5:\"badge\";s:13:\"Tenor Singkat\";s:9:\"highlight\";s:0:\"\";s:4:\"desc\";s:74:\"Likuiditas cepat dan fleksibel untuk perputaran dana jangka sangat pendek.\";s:3:\"aro\";s:12:\"ARO Tersedia\";s:5:\"equiv\";s:0:\"\";s:5:\"image\";s:0:\"\";s:10:\"is_popular\";i:0;s:6:\"urutan\";i:1;}i:1;a:10:{s:5:\"tenor\";s:7:\"3 Bulan\";s:9:\"tenor_num\";i:3;s:5:\"badge\";s:14:\"Tenor Menengah\";s:9:\"highlight\";s:0:\"\";s:4:\"desc\";s:73:\"Kombinasi seimbang antara imbal hasil menarik dan durasi penempatan dana.\";s:3:\"aro\";s:12:\"ARO Tersedia\";s:5:\"equiv\";s:0:\"\";s:5:\"image\";s:0:\"\";s:10:\"is_popular\";i:0;s:6:\"urutan\";i:2;}i:2;a:10:{s:5:\"tenor\";s:7:\"6 Bulan\";s:9:\"tenor_num\";i:6;s:5:\"badge\";s:13:\"Tenor Optimal\";s:9:\"highlight\";s:0:\"\";s:4:\"desc\";s:80:\"Pilihan populer untuk alokasi dana semesteran dengan nisbah lebih menguntungkan.\";s:3:\"aro\";s:12:\"ARO Tersedia\";s:5:\"equiv\";s:0:\"\";s:5:\"image\";s:0:\"\";s:10:\"is_popular\";i:0;s:6:\"urutan\";i:3;}i:3;a:10:{s:5:\"tenor\";s:8:\"12 Bulan\";s:9:\"tenor_num\";i:12;s:5:\"badge\";s:13:\"Tenor Panjang\";s:9:\"highlight\";s:15:\"Hasil Tertinggi\";s:4:\"desc\";s:77:\"Pertumbuhan investasi maksimal dengan porsi nisbah bagi hasil paling optimal.\";s:3:\"aro\";s:12:\"ARO Tersedia\";s:5:\"equiv\";s:0:\"\";s:5:\"image\";s:0:\"\";s:10:\"is_popular\";i:1;s:6:\"urutan\";i:4;}}','auto');
